#!/usr/bin/env bash
# Local FFmpeg Render Script for S01E001 - "The Eight-Beat Failure"
# Generated by Ternfall Studio for Windows/WSL2 & Linux single-operator production

set -euo pipefail

PROD_ROOT="./data/production_root/projects/proj_ternfall_01"
OUT_DIR="$PROD_ROOT/renders/S01E001"
mkdir -p "$OUT_DIR"

echo "=== Ternfall Studio: Rendering S01E001 ==="
command -v ffmpeg >/dev/null 2>&1 || { echo >&2 "[ERROR] ffmpeg is not installed. Install via: sudo apt install ffmpeg"; exit 1; }
command -v ffprobe >/dev/null 2>&1 || { echo >&2 "[ERROR] ffprobe is not installed."; exit 1; }

# Render master 1080p 24fps MP4 with 16:9 aspect ratio and stereo AAC
echo "Running FFmpeg composite..."
ffmpeg -y \
  -f lavfi -i color=c=0x0a0f1d:s=1920x1080:r=24 \
  -f lavfi -i anullsrc=r=44100:cl=stereo \
  -t 15 \
  -c:v libx264 -preset fast -crf 18 -pix_fmt yuv420p \
  -c:a aac -b:a 192k \
  -shortest \
  "$OUT_DIR/S01E001_composite_1080p.mp4"

echo "=== Render Complete: $OUT_DIR/S01E001_composite_1080p.mp4 ==="
ffprobe -v error -show_entries format=duration,size:stream=width,height,codec_name -of default=noprint_wrappers=1 "$OUT_DIR/S01E001_composite_1080p.mp4"
